import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { validateRecordedFlowReport } from "../app/components/recorded-flow-vector-state.ts";

// Generated by the actual read-only inspector from the explicit synthetic
// contract store in test_recorded_field_vectors.py. No camera or private records.
const frozen = JSON.parse(readFileSync(new URL("./fixtures/recorded-flow-vector-report.json", import.meta.url), "utf8"));
const fixture = () => structuredClone(frozen);
const validate = report => validateRecordedFlowReport(report, "flow-test");
const rejected = report => assert.throws(() => validate(report), /No result was accepted/);

test("actual frozen synthetic contract report preserves all support denominators and labels", () => {
  const report = fixture(), before = JSON.stringify(report);
  assert.equal(validate(report), report);
  assert.equal(JSON.stringify(report), before);
  assert.equal(report.data_origin, "SYNTHETIC_CAPTURE_REPLAY");
  assert.equal(report.coverage.supported_sample_count, 3);
  assert.equal(report.coverage.validation_sample_count, 6);
  assert.equal(report.coverage.supported_fraction, 0.5);
  assert.ok(Math.abs(report.metrics.vector_rmse_cm_s - 1) < 1e-8);
});

test("another flow, overlap or missing provenance cannot be shown for this frozen fit", () => {
  assert.throws(() => validateRecordedFlowReport(fixture(), "different-flow"), /No result was accepted/);
  for (const mutate of [
    r => { r.flow_id = "different-flow"; },
    r => { r.flow_content_hash = "not-a-hash"; },
    r => { r.provenance.validation_recording_ids[0] = "training"; },
    r => { r.provenance.frame_splits_disjoint = false; },
    r => { r.recordings[0].recording_id = "unrelated-recording"; },
  ]) { const r = fixture(); mutate(r); rejected(r); }
});

test("units, physical claims, synthetic relabeling and side effects are rejected", () => {
  for (const mutate of [
    r => { r.velocity_units = "m/s"; },
    r => { r.position_units = "m"; },
    r => { r.physical_validation = true; },
    r => { r.capture_independently_verified = true; },
    r => { r.data_origin = "MEASURED_TANK"; },
    r => { r.recordings[0].data_origin = "RECORDED_TANK_CAPTURE_UNVERIFIED"; },
    r => { r.recordings[0].vectors[0].data_origin = "MEASURED_TANK"; },
    r => { r.provider_calls = true; },
    r => { r.refit_performed = true; },
    r => { r.scope = "FREE_RUNNING_FORECAST"; },
  ]) { const r = fixture(); mutate(r); rejected(r); }
});

test("unsupported observations stay present but cannot acquire predictions or invented zero errors", () => {
  const report = fixture(), far = report.recordings[1];
  assert.ok(far.vectors.every(v => !v.supported && v.vector_error_cm_s === null && v.predicted_vx_cm_s === null));
  assert.equal(far.metrics.vector_rmse_cm_s, null);
  validate(report);
  for (const field of ["predicted_vx_cm_s", "residual_vx_cm_s", "vector_error_cm_s", "direction_error_deg"]) {
    const r = fixture(); r.recordings[1].vectors[0][field] = 0; rejected(r);
  }
});

test("component sign, vector magnitude, directions and aggregate errors must reconstruct", () => {
  for (const mutate of [
    r => { r.recordings[0].vectors[0].residual_vx_cm_s *= -1; },
    r => { r.recordings[0].vectors[0].vector_error_cm_s = 0; },
    r => { r.recordings[0].vectors[0].direction_error_deg = 90; },
    r => { r.recordings[0].metrics.vector_rmse_cm_s = 0; },
    r => { r.metrics.equal_recording_mean_rmse_cm_s = 0; },
    r => { r.metrics.mean_speed_bias_cm_s = 0; },
  ]) { const r = fixture(); mutate(r); rejected(r); }
});

test("counts cannot hide unsupported intervals or turn nonoverlapping vectors into extra measurements", () => {
  for (const mutate of [
    r => { r.coverage.validation_sample_count = 3; },
    r => { r.coverage.supported_fraction = 1; },
    r => { r.recordings[1].vectors.pop(); },
    r => { r.recordings[0].counts.observed_point_count = 2; },
    r => { r.recordings[0].counts.missing_point_count = 3; },
  ]) { const r = fixture(); mutate(r); rejected(r); }
});

test("nonfinite coordinates or velocity components never reach SVG rendering", () => {
  for (const field of ["x_cm", "observed_vx_cm_s", "predicted_vx_cm_s", "residual_vy_cm_s"]) {
    for (const value of [NaN, Infinity, -Infinity]) {
      const r = fixture(); r.recordings[0].vectors[0][field] = value; rejected(r);
    }
  }
});
